// A minimal stand-in for `effect/Effect`, enough to run the service shaking
// fixtures. An Effect is an object whose `run(context, scope)` returns a
// Promise; `scope` collects finalizers. Only the API names and call shapes
// matter to the bundler; the real package is covered by @effect/bundle tests.
const EffectProto = {
  *[Symbol.iterator]() {
    return yield this
  }
}

export const make = (run) => Object.assign(Object.create(EffectProto), { run })

export const succeed = (value) => make(async () => value)

export const sync = (evaluate) => make(async () => evaluate())

export const map = (self, f) => make(async (context, scope) => f(await self.run(context, scope)))

export const flatMap = (self, f) =>
  make(async (context, scope) => f(await self.run(context, scope)).run(context, scope))

export const gen = (body) =>
  make(async (context, scope) => {
    const iterator = body()
    let input
    for (;;) {
      const { value, done } = iterator.next(input)
      if (done) return value
      input = await value.run(context, scope)
    }
  })

export const acquireRelease = (acquire, release) =>
  make(async (context, scope) => {
    const value = await acquire.run(context, scope)
    scope.push(() => release(value).run(context, scope))
    return value
  })

export const context = () => make(async (context) => context)

const closeScope = async (scope) => {
  for (const finalizer of scope.reverse()) await finalizer()
}

export const provide = (self, layer) =>
  make(async (context) => {
    const scope = []
    try {
      return await self.run(await layer.build(context, scope), scope)
    } finally {
      await closeScope(scope)
    }
  })

export const runPromise = async (self) => {
  const scope = []
  try {
    return await self.run(new Map(), scope)
  } finally {
    await closeScope(scope)
  }
}
